html, body { margin: 0; height: 100%; min-height: 100vh; font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif; background: #F9F9F9; }

.pc { max-width: 1100px; margin: 0 auto; padding: 26px; }

.pc__header { margin-bottom: 18px; }
.pc__title { font-size: 17px; font-weight: 700; color: #1D2751; }
.pc__subtitle { margin-top: 2px; font-size: 12px; color: #4A5568; }

.pc__layout { display: grid; grid-template-columns: 220px 1fr; gap: 20px; align-items: start; }

.pc__sidebar {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 16px;
  padding: 18px;
  position: sticky;
  top: 0;
}

.pc__progreso-label { font-size: 10.5px; font-weight: 700; letter-spacing: 0.4px; text-transform: uppercase; color: #9CA3AF; }
.pc__progreso-track { margin-top: 8px; height: 8px; background: #F1F3F7; border-radius: 999px; overflow: hidden; }
.pc__progreso-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%); border-radius: 999px; transition: width 0.4s ease-out; }
.pc__progreso-pct { margin-top: 6px; font-size: 20px; font-weight: 800; color: #14327D; }

.pc__pasos { margin-top: 20px; display: flex; flex-direction: column; gap: 4px; }

.pc__paso {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px;
  border-radius: 9px;
  border: none;
  background: none;
  cursor: pointer;
  text-align: left;
  font-size: 12.5px;
  font-weight: 500;
  color: #4A5568;
}
.pc__paso:hover { background: #F1F5F9; }
.pc__paso.activo { background: rgba(30,95,168,.1); color: #14327D; font-weight: 700; }
.pc__paso.no-alcanzado { opacity: 0.45; cursor: not-allowed; }

.pc__paso-numero {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: #E5E7EB;
  color: #6B7280;
  font-size: 10.5px;
  font-weight: 700;
  flex-shrink: 0;
}
.pc__paso.activo .pc__paso-numero { background: #1E5FA8; color: #fff; }
.pc__paso.completo .pc__paso-numero { background: #F4880A; color: #fff; }

.pc__contenido {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 16px;
  padding: 26px;
  min-height: 400px;
}

.pc__seccion-titulo { font-size: 15px; font-weight: 700; color: #14327D; margin-bottom: 4px; }
.pc__seccion-hint { font-size: 12px; color: #4A5568; margin-bottom: 18px; }

.pc__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px 20px; }

.pc__campo { display: flex; flex-direction: column; gap: 5px; }
.pc__campo--full { grid-column: 1 / -1; }

.pc__label { font-size: 11.5px; font-weight: 600; color: #374151; }
.pc__label .req { color: #D6202A; margin-left: 2px; }

.pc__input, .pc__select {
  padding: 9px 12px;
  border: 1px solid #D1D5DB;
  border-radius: 8px;
  font-size: 13px;
  font-family: inherit;
  color: #1F2937;
  background: #fff;
}
.pc__input:focus, .pc__select:focus { outline: none; border-color: #1E5FA8; box-shadow: 0 0 0 2px rgba(30,95,168,.15); }
.pc__input.error, .pc__select.error { border-color: #D6202A; }

.pc__error-banner {
  background: #FCECEC;
  border: 1px solid #F2C9C9;
  border-radius: 10px;
  padding: 12px 16px;
  margin-bottom: 16px;
  font-size: 12px;
  color: #A61620;
}
.pc__error-banner ul { margin: 6px 0 0; padding-left: 18px; }

.pc__nav { display: flex; justify-content: space-between; margin-top: 24px; padding-top: 18px; border-top: 1px solid #F1F3F7; }

.pc__btn {
  padding: 9px 20px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  border: none;
}
.pc__btn--primary { background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%); color: #fff; }
.pc__btn--ghost { background: #fff; border: 1.5px solid #6FA3DC; color: #14327D; }
.pc__btn:disabled { opacity: 0.4; cursor: not-allowed; }

