/**
 * Piloto de "Perfil del Cliente" (MB-FOR-23-013) — 2 de 8 secciones reales
 * (Categoría + Información Personal), como prueba antes de construir el
 * wizard completo. Portado de perfilClienteSchema.ts / SecCategoria.svelte /
 * SecInformacionPersonal.svelte del dashboard Svelte/React de referencia.
 *
 * Estado en memoria del propio widget (no en appsmith.store todavía — para
 * este piloto basta, se decide en la siguiente fase si conviene persistir en
 * store para sobrevivir un remount del iframe).
 */

const CATEGORIAS = [
  { value: "TITULAR", label: "Titular" },
  { value: "CO_TITULAR", label: "Co-Titular" },
  { value: "FIRMANTE", label: "Firmante" },
  { value: "CO_DEUDOR", label: "Co-Deudor" },
  { value: "FIADOR", label: "Fiador" },
  { value: "GARANTE", label: "Garante" },
];

const PAISES = ["Panamá", "Colombia", "Estados Unidos", "México", "Costa Rica", "Venezuela", "España", "Argentina", "Chile", "Perú", "Ecuador", "Brasil", "Canadá", "Otro"]
  .map((p) => ({ value: p, label: p }));

const ESTADO_CIVIL = [
  { value: "SOLTERO", label: "Soltero/a" },
  { value: "CASADO", label: "Casado/a" },
  { value: "DIVORCIADO", label: "Divorciado/a" },
  { value: "VIUDO", label: "Viudo/a" },
  { value: "UNION_LIBRE", label: "Unión Libre" },
];

const SEXO = [
  { value: "F", label: "Femenino" },
  { value: "M", label: "Masculino" },
];

function crearFormVacio() {
  return {
    categoriaCliente: "",
    informacionPersonal: {
      primerNombre: "", segundoNombre: "", primerApellido: "", segundoApellido: "",
      cedula: "", paisEmisorDocumento: "", nacionalidad: "", sexo: "",
      fechaNacimiento: "", paisNacimiento: "", estadoCivil: "",
      correoElectronico: "", celular: "",
    },
  };
}

let form = crearFormVacio();
let pasoActivo = 0;
let pasoMaximo = 0;

const SECCIONES = [
  {
    id: "categoria",
    titulo: "Categoría del Cliente",
    hint: "Seleccione el rol del cliente: Titular, Co-Titular, Firmante, etc.",
    validate: (f) => (req(f.categoriaCliente) ? [] : ["Categoría del cliente"]),
  },
  {
    id: "informacionPersonal",
    titulo: "Información Personal",
    hint: "Datos de identificación básicos del cliente.",
    validate: (f) => {
      const e = [];
      const p = f.informacionPersonal;
      if (!req(p.primerNombre)) e.push("Primer Nombre");
      if (!req(p.primerApellido)) e.push("Primer Apellido");
      if (!req(p.cedula) || p.cedula.trim().length < 5) e.push("Cédula (mínimo 5 caracteres)");
      if (!req(p.paisEmisorDocumento)) e.push("País Emisor del documento");
      if (!req(p.nacionalidad)) e.push("Nacionalidad");
      if (!req(p.sexo)) e.push("Sexo");
      if (!req(p.fechaNacimiento)) e.push("Fecha de Nacimiento");
      if (!req(p.paisNacimiento)) e.push("País de Nacimiento");
      if (!req(p.estadoCivil)) e.push("Estado Civil");
      if (!req(p.correoElectronico)) e.push("Correo Electrónico");
      else if (!isEmail(p.correoElectronico)) e.push("Correo Electrónico (formato inválido)");
      if (!req(p.celular)) e.push("Celular");
      return e;
    },
  },
];

function req(v) {
  if (v == null) return false;
  if (typeof v === "string") return v.trim() !== "";
  if (typeof v === "number") return !isNaN(v);
  return Boolean(v);
}
function isEmail(v) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
}

/** Mismo algoritmo que calcularProgreso() de perfilClienteSchema.ts: cuenta
 * campos hoja diligenciados sobre el total, recorriendo recursivamente. */
function contarCampos(valor) {
  if (Array.isArray(valor)) {
    return valor.reduce((acc, item) => {
      const r = contarCampos(item);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (valor !== null && typeof valor === "object") {
    return Object.values(valor).reduce((acc, v) => {
      const r = contarCampos(v);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (typeof valor === "string") return { total: 1, completos: valor.trim() !== "" ? 1 : 0 };
  if (typeof valor === "number") return { total: 1, completos: !isNaN(valor) && valor !== 0 ? 1 : 0 };
  return { total: 0, completos: 0 };
}
function calcularProgreso(f) {
  const { total, completos } = contarCampos(f);
  if (total === 0) return 0;
  return Math.round((completos / total) * 100);
}

function irAPaso(i) {
  if (i > pasoMaximo) return;
  pasoActivo = i;
  renderTodo();
}

function avanzar() {
  const errores = SECCIONES[pasoActivo].validate(form);
  if (errores.length > 0) {
    renderContenido(errores);
    return;
  }
  if (pasoActivo < SECCIONES.length - 1) {
    pasoActivo += 1;
    if (pasoActivo > pasoMaximo) pasoMaximo = pasoActivo;
  }
  renderTodo();
}

function retroceder() {
  if (pasoActivo > 0) {
    pasoActivo -= 1;
    renderTodo();
  }
}

function renderTodo() {
  renderProgreso();
  renderPasos();
  renderContenido([]);
}

function renderProgreso() {
  const pct = calcularProgreso(form);
  const fill = document.getElementById("pc-progreso-fill");
  const label = document.getElementById("pc-progreso-pct");
  if (fill) fill.style.width = pct + "%";
  if (label) label.textContent = pct + "%";
}

function renderPasos() {
  const nav = document.getElementById("pc-pasos");
  if (!nav) return;
  nav.innerHTML = "";
  SECCIONES.forEach((s, i) => {
    const alcanzado = i <= pasoMaximo;
    const completo = pasoMaximo > i && s.validate(form).length === 0;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pc__paso" + (i === pasoActivo ? " activo" : "") + (!alcanzado ? " no-alcanzado" : "") + (completo ? " completo" : "");
    btn.disabled = !alcanzado;

    const numero = document.createElement("span");
    numero.className = "pc__paso-numero";
    numero.textContent = String(i + 1);
    btn.appendChild(numero);

    const label = document.createElement("span");
    label.textContent = s.titulo;
    btn.appendChild(label);

    btn.addEventListener("click", () => irAPaso(i));
    nav.appendChild(btn);
  });
}

function campoTexto(labelText, valor, onInput, required) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const input = document.createElement("input");
  input.className = "pc__input";
  input.type = "text";
  input.value = valor || "";
  input.addEventListener("input", (e) => onInput(e.target.value));
  wrap.appendChild(input);
  return wrap;
}

function campoFecha(labelText, valor, onInput, required) {
  const wrap = campoTexto(labelText, valor, onInput, required);
  wrap.querySelector("input").type = "date";
  return wrap;
}

function campoSelect(labelText, valor, opciones, onChange, required) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const select = document.createElement("select");
  select.className = "pc__select";
  const optVacio = document.createElement("option");
  optVacio.value = "";
  optVacio.textContent = "Seleccione...";
  select.appendChild(optVacio);
  opciones.forEach((o) => {
    const opt = document.createElement("option");
    opt.value = o.value;
    opt.textContent = o.label;
    if (o.value === valor) opt.selected = true;
    select.appendChild(opt);
  });
  select.addEventListener("change", (e) => onChange(e.target.value));
  wrap.appendChild(select);
  return wrap;
}

function renderContenido(erroresForzados) {
  const cont = document.getElementById("pc-contenido");
  if (!cont) return;
  cont.innerHTML = "";

  const seccion = SECCIONES[pasoActivo];

  if (erroresForzados && erroresForzados.length > 0) {
    const banner = document.createElement("div");
    banner.className = "pc__error-banner";
    banner.innerHTML = "Faltan campos por completar:<ul>" + erroresForzados.map((e) => "<li>" + e + "</li>").join("") + "</ul>";
    cont.appendChild(banner);
  }

  const titulo = document.createElement("div");
  titulo.className = "pc__seccion-titulo";
  titulo.textContent = seccion.titulo;
  cont.appendChild(titulo);

  const hint = document.createElement("div");
  hint.className = "pc__seccion-hint";
  hint.textContent = seccion.hint;
  cont.appendChild(hint);

  const grid = document.createElement("div");
  grid.className = "pc__grid";
  cont.appendChild(grid);

  if (seccion.id === "categoria") {
    grid.appendChild(campoSelect("Categoría", form.categoriaCliente, CATEGORIAS, (v) => { form.categoriaCliente = v; renderProgreso(); }, true));
  }

  if (seccion.id === "informacionPersonal") {
    const p = form.informacionPersonal;
    grid.appendChild(campoTexto("Primer Nombre", p.primerNombre, (v) => { p.primerNombre = v; renderProgreso(); }, true));
    grid.appendChild(campoTexto("Segundo Nombre", p.segundoNombre, (v) => { p.segundoNombre = v; renderProgreso(); }, false));
    grid.appendChild(campoTexto("Primer Apellido", p.primerApellido, (v) => { p.primerApellido = v; renderProgreso(); }, true));
    grid.appendChild(campoTexto("Segundo Apellido", p.segundoApellido, (v) => { p.segundoApellido = v; renderProgreso(); }, false));
    grid.appendChild(campoTexto("Cédula / Documento", p.cedula, (v) => { p.cedula = v; renderProgreso(); }, true));
    grid.appendChild(campoSelect("País Emisor", p.paisEmisorDocumento, PAISES, (v) => { p.paisEmisorDocumento = v; renderProgreso(); }, true));
    grid.appendChild(campoSelect("Nacionalidad", p.nacionalidad, PAISES, (v) => { p.nacionalidad = v; renderProgreso(); }, true));
    grid.appendChild(campoSelect("Sexo", p.sexo, SEXO, (v) => { p.sexo = v; renderProgreso(); }, true));
    grid.appendChild(campoFecha("Fecha de Nacimiento", p.fechaNacimiento, (v) => { p.fechaNacimiento = v; renderProgreso(); }, true));
    grid.appendChild(campoSelect("País de Nacimiento", p.paisNacimiento, PAISES, (v) => { p.paisNacimiento = v; renderProgreso(); }, true));
    grid.appendChild(campoSelect("Estado Civil", p.estadoCivil, ESTADO_CIVIL, (v) => { p.estadoCivil = v; renderProgreso(); }, true));
    grid.appendChild(campoTexto("Correo Electrónico", p.correoElectronico, (v) => { p.correoElectronico = v; renderProgreso(); }, true));
    grid.appendChild(campoTexto("Celular", p.celular, (v) => { p.celular = v; renderProgreso(); }, true));
  }

  const nav = document.createElement("div");
  nav.className = "pc__nav";

  const btnAtras = document.createElement("button");
  btnAtras.type = "button";
  btnAtras.className = "pc__btn pc__btn--ghost";
  btnAtras.textContent = "Atrás";
  btnAtras.disabled = pasoActivo === 0;
  btnAtras.addEventListener("click", retroceder);
  nav.appendChild(btnAtras);

  const btnSiguiente = document.createElement("button");
  btnSiguiente.type = "button";
  btnSiguiente.className = "pc__btn pc__btn--primary";
  btnSiguiente.textContent = pasoActivo === SECCIONES.length - 1 ? "Finalizar (piloto)" : "Siguiente";
  btnSiguiente.addEventListener("click", avanzar);
  nav.appendChild(btnSiguiente);

  cont.appendChild(nav);
}

appsmith.onReady(() => {
  renderTodo();
});

